const hostMap={app:'app',editor:'editor',wp:'wp',serp:'serp'};
let session={},sites=[],connections=[],site=null,pageIndex=0,activeSection=0,dirty=false,filter='all',serpTab='rankings';
const baseDomain=document.querySelector('meta[name="rankleem-domain"]')?.content||'';
const production=Boolean(baseDomain&&(location.hostname===baseDomain||location.hostname.endsWith('.'+baseDomain)));
const route=location.pathname==='/'?(hostMap[location.hostname.split('.')[0]]||'landing'):location.pathname.slice(1);
function href(name,query=''){const sub=['editor','wp','serp'].includes(name)?name:['app','publish','integrations','domains','jobs','login'].includes(name)?'app':'';return production?`https://${sub?sub+'.':''}${baseDomain}${['app','editor','wp','serp','landing'].includes(name)?'/':'/'+name}${query}`:`${name==='landing'?'/':'/'+name}${query}`;}
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const logo="<span class=\"logo\"><img class=\"brand-lockup\" src=\"/assets/brand/logo.svg\" alt=\"Sitocal\" width=\"155\" height=\"47\"></span>",darkLogo="<span class=\"logo\"><img class=\"brand-lockup\" src=\"/assets/brand/logo-dark.svg\" alt=\"Sitocal\" width=\"155\" height=\"47\"></span>";
const button=(text,action,klass='')=>`<button class="btn ${klass}" data-action="${action}">${text}</button>`;
function notify(text){const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.style.display='none',6000);}
async function api(url,options={}){const {body,...rest}=options;const res=await fetch(url,{...rest,headers:{...(body instanceof ArrayBuffer?{'Content-Type':'application/zip'}:{'Content-Type':'application/json'}),'X-CSRF-Token':session.csrf||'',...options.headers},body:body===undefined?undefined:body instanceof ArrayBuffer?body:JSON.stringify(body)});if(!res.ok){let data;try{data=await res.json();}catch{}throw Error(data?.error||`Request failed (${res.status})`);}return res.json();}
function dialog(html){modalContent.innerHTML=html;modal.showModal();}
function loading(message='Loading your workspace…'){return `<div class="empty"><div class="eyebrow">SITOCAL</div><h2>${esc(message)}</h2><div class="progress-bar"><span></span></div></div>`;}
function selected(){return site||sites[0];}
function sitePicker(id='project'){return `<label class="field">Website<select name="${id}" id="${id}">${sites.map(s=>`<option value="${s.id}" ${s.id===selected()?.id?'selected':''}>${esc(s.data.business)}</option>`).join('')}</select></label>`;}
function date(s){return new Date(s).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
const featureLinks=[['01','Build a better first impression.','Turn business details into a structured, responsive local website. Keep your services, locations and content together.','app','Open the builder'],['02','Make every word your own.','Click text directly in your site preview, edit it, and save a revision. Download your website whenever you need it.','editor','Explore the editor'],['03','Keep an eye on your visibility.','Connect a SERP provider to check rankings and competitors. Link Google for Search Console and GA4 reporting.','serp','Open search workspace']];
