function auth(register=false){root.innerHTML=`<div class="auth"><a href="${href('landing')}">${logo}</a><div class="panel"><div class="eyebrow muted">Your local advantage starts here</div><h1 style="margin-top:15px">${register?'A little room to grow.':'Good to see you again.'}</h1><p style="font-size:13px">${register?'Create your Sitocal account and start your first project.':'Sign in to your Sitocal workspace.'}</p><form id="auth-form" data-register="${register}"><label class="field">Email address<input name="email" type="email" autocomplete="email" required></label><label class="field">Password<input name="password" type="password" minlength="12" maxlength="200" autocomplete="${register?'new-password':'current-password'}" required><div class="hint">At least 12 characters.</div></label>${register?'<label class="field">Invite code<input name="invite" type="password" autocomplete="off"><div class="hint">Enter the private test invite code, if required.</div></label>':''}<p class="error" id="auth-error" role="alert"></p><button class="btn primary" type="submit">${register?'Create account':'Sign in'} ↗</button></form><button class="btn ghost auth-switch" data-action="${register?'signin':'signup'}">${register?'Already have an account? Sign in':'New here? Create an account'}</button></div><a class="auth-back" href="${href('landing')}">← Back to Sitocal</a><div class="alert">Local development alpha. Email verification and password recovery are not yet available.</div></div>`;}
const navItems=[['app','◫','Overview'],['editor','▤','Site editor'],['wp','↔','WordPress converter'],['serp','↗','SERP engine'],['domains','◎','Find a domain'],['publish','↑','Publish website'],['integrations','◇','Integrations'],['jobs','≡','Activity']];
function shell(content,name=route){const nav=navItems.find(x=>x[0]===name);root.innerHTML=`<div class="workspace"><header class="fieldwork-top"><a href="${href('app')}" aria-label="Sitocal workspace">${darkLogo}</a><nav class="fieldwork-nav" aria-label="Workspace navigation">${navItems.map(([r,icon,text])=>`<a class="${name===r?'active':''}" ${name===r?'aria-current="page"':''} href="${href(r)}">${text}</a>`).join('')}</nav><div class="fieldwork-account"><span class="avatar" title="Signed in">${esc(session.user.email.slice(0,2).toUpperCase())}</span><button class="btn small" data-action="logout">Sign out</button></div></header><div><div class="topbar"><span class="muted">Workspace &nbsp; / &nbsp; <strong style="color:var(--ink)">${nav?.[2]||'Overview'}</strong></span><span class="badge neutral">Private alpha</span></div><main class="content">${content}</main><footer class="workspace-footer"><a href="${href('landing')}" aria-label="Sitocal home">${logo}</a><span class="footer-copy">Build locally. Grow visibly. · ${esc(production?location.hostname:'Local preview')}<br>Provider results appear after completed requests.</span><a class="text-link" href="${href('integrations')}">Manage connections →</a></footer></div></div>`;}
function header(title,copy,action=''){return `<div class="page-header row between"><div><h1>${title}</h1><p>${copy}</p></div>${action}</div>`;}
function card(s){return `<article class="site-card"><div class="site-browser"><span class="browser-dot"></span><span class="browser-dot"></span><span class="browser-dot"></span><span style="margin-left:8px">Private project · ${esc(s.data.city)}</span></div><div class="site-mini ${s.data.theme}"><div class="mini-brand">${esc(s.data.business.toUpperCase())}</div><div class="mini-headline">${esc(s.data.pages[0].sections[0]?.heading)}</div><div class="mini-shape" aria-hidden="true"></div></div><div class="site-info"><div class="row between"><h3>${esc(s.data.business)}</h3><span class="badge">Draft</span></div><p>${s.data.pages.length} pages · ${esc(s.data.city)} · Updated ${date(s.updated)}</p><div class="row bottom"><a class="text-link" href="${href('editor','?site='+s.id)}">Continue editing →</a><a class="btn small" href="${href('publish','?site='+s.id)}">Publish ↗</a></div></div></article>`;}
function overview(){
const count=sites.reduce((n,s)=>n+s.data.pages.length,0),research=connections.includes('dataforseo'),steps=[['Account created',true,'Your personal workspace is ready.'],['First website generated',sites.length>0,sites.length?'Your saved drafts are ready to edit.':'Create a website to start your local presence.'],['Provider credentials added',connections.length>0,connections.length?'Credentials saved; verify with a controlled request.':'Connect the services you want to use.'],['Search research configured',research,research?'Run a rank check to collect your first result.':'Add DataForSEO to begin ranking research.']];
shell(`<section class="fieldwork-intro"><div><div class="eyebrow muted">BUILD LOCALLY. GROW VISIBLY.</div><h1>Your local growth workspace.</h1><p>Your websites, content and search research in one place.</p></div>${button('+ Create website','new-site','primary')}</section><section class="stats-row" aria-label="Workspace summary"><div class="stat"><span class="stat-label">Saved websites</span><div class="stat-value">${sites.length}</div><small>Drafts in your account</small></div><div class="stat"><span class="stat-label">Website pages</span><div class="stat-value">${count}</div><small>Across your saved sites</small></div><div class="stat"><span class="stat-label">Provider credentials</span><div class="stat-value">${connections.length}</div><small>Saved · verification required</small></div><div class="stat"><span class="stat-label">Search provider</span><div class="stat-value word">${research?'Configured':'Not configured'}</div><small>${research?'Ready for your first request':'Connect in Integrations'}</small></div></section><div class="fieldwork-panels"><section class="panel"><div class="row between"><h2>Visibility, moving forward.</h2><span class="badge neutral">Search workspace</span></div><p class="section-caption">Track organic visibility with your connected research provider.</p><div class="research-empty"><div><img class="brand-symbol" src="/assets/brand/icon.svg" alt="" width="35" height="35"><p>${research?'Open the SERP engine to run a check or review recorded observations.':'Connect a search provider to begin collecting rank observations. Your overview does not yet aggregate rank history.'}</p><a class="btn small" href="${href(research?'serp':'integrations')}">${research?'Open SERP engine':'Connect search provider'} ↗</a></div></div></section><section class="panel"><div class="row between"><h2>Your next best steps</h2><span class="badge">${steps.filter(s=>s[1]).length} of 4 ready</span></div><ul class="checklist">${steps.map(([title,done,copy],i)=>`<li><span class="check" aria-hidden="true">${done?'✓':i+1}</span><div><strong>${title}</strong><small>${copy}</small></div></li>`).join('')}</ul></section></div><section class="panel portfolio"><div class="row between"><div><h2>Websites & local visibility</h2><p class="section-caption">Your saved drafts. Open a website to continue editing.</p></div><div class="row"><label class="btn small import-label">Import ZIP<input type="file" accept=".zip" data-import hidden></label><a class="btn small" href="${href('serp')}">Open SERP engine ↗</a></div></div>${sites.length?`<div class="table-scroll"><table><thead><tr><th>Business / website</th><th>Status</th><th>Pages</th><th>Service area</th><th>Last updated</th><th></th></tr></thead><tbody>${sites.map(s=>`<tr><td><div class="business-cell"><span class="avatar">${esc(s.data.business.slice(0,1).toUpperCase())}</span><div><strong>${esc(s.data.business)}</strong><small>Private project · ${esc(s.data.theme)}</small></div></div></td><td><span class="badge neutral">Saved draft</span></td><td>${s.data.pages.length}</td><td>${esc(s.data.city)}</td><td>${date(s.updated)}</td><td><a class="text-link" href="${href('editor','?site='+s.id)}">Edit website →</a></td></tr>`).join('')}</tbody></table></div>`:`<div class="portfolio-empty"><h3>Your next local success starts here.</h3><p>Add your business details to generate an editable website draft.</p>${button('Create your first website','new-site','primary')}</div>`}</section>`,'app');}
function newSite(){dialog(`<div class="eyebrow muted">YOUR NEXT LOCAL SUCCESS</div><h2 style="font:32px Georgia,serif;margin-top:13px">Let’s start with the business.</h2><p style="font-size:12px">Generate a template draft offline, or use your connected AI provider. Review every page before publishing.</p><form id="create-site"><div class="grid2"><label class="field">Business name<input name="business" maxlength="120" placeholder="Austin Flow Plumbing" required></label><label class="field">Service area<input name="city" maxlength="120" placeholder="Austin, Texas" required></label></div><label class="field">Generation mode<select name="generation"><option value="template">Template draft · No API required</option><option value="ai">AI draft · Connected OpenAI account required</option></select><div class="hint">AI mode sends your business brief to OpenAI and uses your API credits.</div></label><label class="field">Services, separated by commas<input name="services" maxlength="1000" placeholder="Drain cleaning, Water heater repair" required><div class="hint">Home, About, Services, Contact and a detailed page per service. Up to 8 services.</div></label><label class="field">About your business (optional)<textarea name="businessBrief" maxlength="2000" rows="4" placeholder="Describe what you do, who you serve and your approach. Include only facts you can verify."></textarea><div class="hint">Used on your Home and About pages. No invented reviews, prices or qualifications.</div></label><div class="grid2"><label class="field">Public phone (optional)<input name="phone" maxlength="60" type="tel"></label><label class="field">Public email (optional)<input name="email" maxlength="150" type="email"></label></div><div class="grid2"><label class="field">Website style<select name="theme"><option value="orchard">Orchard · Forest & ivory</option><option value="clay">Clay · Warm & grounded</option><option value="slate">Slate · Crisp & confident</option></select></label><label class="field">Accent color<input name="accent" type="color" value="#196747"></label></div><div class="hint">Content is a draft. Verify all business facts before publication.</div><div class="form-actions"><button class="btn primary" type="submit">Create website draft ↗</button></div></form>`);}
async function editor(){if(!sites.length)return shell(header('A little more you.','Create or import a website to start editing.')+`<div class="panel empty"><h2>Your editor is ready.</h2><p>Sitocal websites retain editable page sections and revision history.</p><div class="row" style="justify-content:center">${button('Create a website','new-site','primary')}<label class="btn import-label">Import ZIP<input type="file" accept=".zip" data-import hidden></label></div></div>`,'editor');site=selected();const p=site.data.pages[pageIndex]||site.data.pages[0];pageIndex=site.data.pages.indexOf(p);activeSection=Math.min(activeSection,p.sections.length-1);const s=p.sections[activeSection];shell(header('Make every word your own.','Click any heading, paragraph or button in the preview to edit it.',`<div class="row"><a class="btn" href="/api/sites/${site.id}/export">Download ZIP ↓</a>${button('Save revision','save-site','primary')}</div>`)+`<div class="editor-toolbar"><div class="row">${sitePicker('editor-project')}<label class="field">Page<select id="editor-page">${site.data.pages.map((p,i)=>`<option value="${i}" ${i===pageIndex?'selected':''}>${esc(p.title)}</option>`).join('')}</select></label></div><div class="segmented"><button data-device="desktop" class="active">Desktop</button><button data-device="mobile">Mobile</button></div></div><div class="split-work"><section class="panel editor-panel"><h3>Page content</h3><label class="field">Section<select id="editor-section">${p.sections.map((s,i)=>`<option value="${i}" ${i===activeSection?'selected':''}>${i+1}. ${esc(s.heading.slice(0,35))}</option>`).join('')}</select></label><label class="field">Heading<input id="edit-heading" maxlength="200" value="${esc(s.heading)}"></label><label class="field">Body<textarea id="edit-body" maxlength="4000">${esc(s.body)}</textarea></label><label class="field">Button label<input id="edit-cta" maxlength="80" value="${esc(s.cta)}"></label>${button('Apply to preview','apply-edit','small primary')}<hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><label class="field">SEO title<input id="edit-title" maxlength="150" value="${esc(p.title)}"></label><label class="field">Meta description<textarea id="edit-description" maxlength="320" style="min-height:80px">${esc(p.description)}</textarea></label><div class="row">${button('+ Add section','add-section','small')}${button('↑','section-up','small')}${button('↓','section-down','small')}${button('Remove','remove-section','small danger')}</div><div class="row" style="margin-top:15px">${button('Revision history','revisions','small ghost')}<span id="save-state" class="hint">${dirty?'Unsaved changes':'All changes saved'}</span></div></section><div class="editor-frame-wrap" id="frame-wrap"><iframe id="site-frame" title="Editable website preview" sandbox="allow-scripts" src="/api/sites/${site.id}/preview?page=${encodeURIComponent(p.slug)}&edit=1"></iframe></div></div>`,'editor');if(dirty)refreshFrame();}
function captureEdit(){if(!site||!document.getElementById('edit-heading'))return;const p=site.data.pages[pageIndex],section=p.sections[activeSection];let changed=false;for(const key of ['heading','body','cta']){const value=document.getElementById('edit-'+key).value;if(section[key]!==value)changed=true;section[key]=value;}for(const key of ['title','description']){const value=document.getElementById('edit-'+key).value;if(p[key]!==value)changed=true;p[key]=value;}if(changed)dirty=true;document.getElementById('save-state').textContent=dirty?'Unsaved changes':'All changes saved';}
async function refreshFrame(){const frame=document.getElementById('site-frame');if(!frame||!site)return;try{const r=await api('/api/sites/'+site.id+'/draft-preview',{method:'POST',body:site.data});frame.src='/api/sites/'+site.id+'/preview?page='+encodeURIComponent(site.data.pages[pageIndex].slug)+'&edit=1&draft='+r.key;}catch(e){notify(e.message);}}
function converter(){shell(header('Your site. A new home.','Turn your Sitocal website into editable content for WordPress.')+`<section class="upload-zone"><div class="eyebrow muted">BRING YOUR WEBSITE</div><h2 style="font:29px Georgia,serif;margin:14px 0">A ZIP file. More possibilities.</h2><p>Upload a Sitocal ZIP to preserve your page structure. Other HTML ZIPs import text into a new editable layout; original styling and scripts are not retained.</p><label class="btn primary import-label">Choose website ZIP ↑<input type="file" accept=".zip" data-import hidden></label></section>${sites.length?`<section class="panel">${sitePicker('convert-project')}<div class="hint" style="margin-bottom:22px">Export scope: headings, body text, buttons and section layout. Not a pixel-perfect HTML-to-builder conversion. Validate imports on your WordPress installation.</div>${[['E','Elementor','Native editable widgets · Individual page JSON templates','elementor'],['W','WordPress / Gutenberg','Native blocks · Paste into the page code editor','gutenberg'],['D','Divi 4 · Beta','WordPress XML + editable text shortcodes · Divi 5 native layouts pending','divi']].map(([symbol,title,copy,format])=>`<div class="converter-option"><span class="convert-letter">${symbol}</span><div><h3>${title}</h3><p>${copy}</p></div>${`<button class="btn small" data-convert="${format}">Download ↓</button>`}</div>`).join('')}<div class="hint">Elementor: unzip → Templates → Saved Templates → Import each JSON. Gutenberg: create a page → Code editor → paste block markup.</div></section>`:'<div class="panel empty"><h2>Start with your first website.</h2><p>Create a Sitocal project or import a ZIP above.</p>'+button('Create a website','new-site','primary')+'</div>'}`,'wp');}
const providerMeta={openai:['AI','OpenAI','Optional AI writing with your own API key and selected model.',['token','model']],github:['GH','GitHub','Push generated files to an initialized repository.',['token','repository','branch']],gitlab:['GL','GitLab','Commit generated files to GitLab.com.',['token','repository','branch']],bitbucket:['BB','Bitbucket','Push files using your account API token.',['email','token','repository','branch']],cloudflare:['CF','Cloudflare Pages','Trigger a build from a connected Git repository.',['hook']],vercel:['▲','Vercel','Create a static deployment from generated files.',['token','project','team']],netlify:['N','Netlify','Upload a static ZIP to an existing Netlify site.',['token','project']],render:['R','Render','Trigger a build from your connected repository.',['token','project']],dataforseo:['↗','DataForSEO','Organic ranks, competitors, demand and research.',['login','password']],registrar:['◎','Cloudflare Registrar','Search domain availability through the registrar API.',['token','account']]};
function integrations(){shell(header('Works with your workflow.','Connect the accounts you want to use. Credentials stay on the server.')+`<div class="alert">Saved credentials are not verified connections. Live requests can consume provider credits or create external resources. Add only accounts you control.</div><div class="integration-grid">${Object.entries(providerMeta).map(([key,[symbol,title,copy]])=>`<article class="panel integration-card"><div class="row between"><div class="integration-symbol">${symbol}</div><span class="badge ${connections.includes(key)?'':'neutral'}">${connections.includes(key)?'Saved · unverified':'Not configured'}</span></div><h3>${title}</h3><p>${copy}</p><div class="row"><button class="btn small" data-configure="${key}">${connections.includes(key)?'Replace credentials':'Configure'}</button>${connections.includes(key)?`<button class="btn small ghost danger" data-disconnect="${key}">Remove</button>`:''}</div></article>`).join('')}<article class="panel integration-card"><div class="integration-symbol">G</div><h3>Google Search & Analytics</h3><p>Read your Search Console and GA4 properties through Google OAuth.</p>${button(connections.includes('google')?'Reconnect Google':'Connect Google','google-connect','small')}${connections.includes('google')?'<button class="btn small ghost danger" data-disconnect="google">Disconnect</button>':''}</article></div><p class="integrations-foot">This alpha stores one configuration per provider per account. Multi-project provider destinations and organization roles are next-stage work.</p>`,'integrations');}
function configure(key){const [symbol,title,copy,fields]=providerMeta[key];dialog(`<div class="eyebrow muted">Connect your workflow</div><h2 style="margin-top:15px">${title}</h2><p style="font-size:12px">${copy}</p><form id="connection-form" data-provider="${key}">${fields.map(f=>`<label class="field">${({model:'Structured-output model ID (available to your API account)',repository:'Repository (owner/name)',project:key==='render'?'Render service ID (srv-…)':key==='netlify'?'Netlify site ID':'Vercel project name',branch:'Branch (existing)',team:'Team ID (optional)',account:'Cloudflare account ID',login:'API login',email:'Bitbucket account email',hook:'Cloudflare Pages deployment hook URL',password:'API password',token:'API token'})[f]||f}<input name="${f}" type="${['token','password','hook'].includes(f)?'password':'text'}" autocomplete="off" ${f==='branch'?'value="main"':''} ${f==='team'?'':'required'}></label>`).join('')}<div class="hint">Existing values are never sent back to the browser. Saving replaces the full configuration. ${['github','gitlab','bitbucket'].includes(key)?'Use an initialized repository and branch. Generated paths are overwritten; unrelated paths remain.':''}${['cloudflare','render'].includes(key)?'Connect the same repository and branch in your hosting dashboard before publishing.':''}</div><div class="form-actions"><button class="btn primary" type="submit">Save credentials</button></div></form>`);}
function domains(){shell(header('Find a place to call yours.','Search a domain through your connected registrar account.')+`<section class="panel" style="max-width:850px"><div class="eyebrow muted">YOUR NEXT LOCAL ADDRESS</div><h2 style="font:32px Georgia,serif;margin-top:15px">A good name deserves a home.</h2><p style="font-size:13px">Check a domain’s availability without leaving Sitocal. Prices and availability are provided by the registrar and may change.</p><form id="domain-form"><label class="field">Domain name<input name="domain" placeholder="yourbusiness.com" required maxlength="253"></label><div class="row"><button class="btn primary" type="submit">Search domain ↗</button><a class="text-link" href="${href('integrations')}">Configure registrar</a></div></form><div id="domain-result" style="margin-top:25px"></div></section><p class="hint">This alpha uses the Cloudflare Registrar API. Account API access is required. Search never purchases or registers a domain.</p>`,'domains');}
function publish(){if(!sites.length)return shell(header('Take your next step.','Create a website before publishing.')+`<div class="panel empty"><h2>A website worth sharing.</h2><p>Start with a draft, review the content and connect your destination.</p>${button('Create a website','new-site','primary')}</div>`,'publish');shell(header('Ready for your next chapter?','Review your website, choose a destination, and publish from one place.')+`<form id="publish-form"><section class="panel publish-step"><h2>Choose your website</h2>${sitePicker('publish-project')}<p class="hint">Generated pages and rankleem.json will be sent to your selected destination. Existing matching repository paths are overwritten. No automatic deletion of old files.</p></section><div class="grid2"><section class="panel publish-step"><h2>Push to a repository</h2><label class="field">Source provider<select name="source"><option value="">Skip repository push</option>${['github','gitlab','bitbucket'].map(key=>`<option value="${key}" ${connections.includes(key)?'':'disabled'}>${providerMeta[key][1]}${connections.includes(key)?'':' — configure first'}</option>`).join('')}</select></label><p class="hint">The existing repository and branch are set in Integrations. Static HTML requires no build command; output directory is the repository root.</p></section><section class="panel publish-step"><h2>Choose a deployment host</h2><label class="field">Hosting provider<select name="host"><option value="">Repository only</option>${['cloudflare','vercel','netlify','render'].map(key=>`<option value="${key}" ${connections.includes(key)?'':'disabled'}>${providerMeta[key][1]}${connections.includes(key)?'':' — configure first'}</option>`).join('')}</select></label><p class="hint">Netlify/Vercel accept file uploads. Cloudflare/Render build from a repository already connected in their dashboard. Use the same repository/branch; triggered is not confirmed live.</p></section></div><section class="panel publish-step"><h2>Review and send</h2><label class="row" style="font-size:12px;align-items:start"><input type="checkbox" name="reviewed" required><span>I reviewed the business facts and authorize writing these files and creating a deployment in my configured provider accounts.</span></label><div class="row" style="margin-top:20px"><button class="btn primary" type="submit">Push & deploy ↗</button><a class="text-link" href="${href('integrations')}">Manage integrations</a></div><div id="publish-result" style="margin-top:20px"></div></section></form>`,'publish');}
function serp(){shell(header('A little more visible.','Research local search, compare competitors and connect your Google properties.')+`<div class="subnav">${[['rankings','Rankings & competitors'],['demand','Search demand'],['traffic','Traffic estimates'],['backlinks','Backlink research'],['google','GSC & GA4'],['history','Rank history']].map(([v,t])=>`<button data-serptab="${v}" class="${serpTab===v?'active':''}">${t}</button>`).join('')}</div><div id="serp-content"></div>`,'serp');renderSerpTab();}
async function renderSerpTab(){const target=document.getElementById('serp-content');if(!target)return;if(serpTab==='history'){target.innerHTML=loading('Loading rank history…');try{const r=await api('/api/serp/history');target.innerHTML=r.observations.length?`<div class="panel table-scroll"><table><thead><tr><th>Keyword</th><th>Domain</th><th>Position</th><th>Configuration</th><th>Checked</th></tr></thead><tbody>${r.observations.map(o=>`<tr><td>${esc(o.config.keyword)}</td><td>${esc(o.config.domain)}</td><td>${o.data.targets[0].position??'Not found in top 100'}</td><td>${esc(o.config.device)} / ${o.config.locationCode}</td><td>${esc(new Date(o.created).toLocaleString())}</td></tr>`).join('')}</tbody></table></div>`:`<div class="panel empty"><h2>A clear starting point.</h2><p>Completed rank checks will appear here. Failed requests never become unranked results.</p></div>`;}catch(e){target.innerHTML=`<p class="error">${esc(e.message)}</p>`;}return;}
if(serpTab==='google'){target.innerHTML=`<section class="panel"><div class="row between"><div><h2>Your data, in good company.</h2><p style="font-size:12px">Read-only access to properties you can access. Google consent and server OAuth configuration are required.</p></div>${button(connections.includes('google')?'Reconnect Google':'Connect Google','google-connect','primary')}</div>${connections.includes('google')?button('Load my Google properties','google-properties','small'):''}<div id="google-properties" style="margin-top:20px"></div><div id="google-result" style="margin-top:20px"></div></section>`;return;}
const kind=serpTab;target.innerHTML=`<div class="alert">${connections.includes('dataforseo')?'Live provider calls can consume your DataForSEO credits. Each action is capped by the server’s daily request limit.':'Connect DataForSEO in Integrations to run this research. No sample figures will be shown as real results.'} ${kind==='traffic'?'Traffic here is a modeled search estimate, not measured visits. Use GA4 for actual property traffic.':''}${kind==='backlinks'?'A separate provider Backlinks subscription may be required.':''}</div><div class="grid2"><section class="panel"><h2>${({rankings:'Where do you show up?',demand:'What are people searching for?',traffic:'Understand a domain’s reach.',backlinks:'See the links behind a domain.'})[kind]}</h2><form id="serp-form" data-kind="${kind}"><label class="field">Website domain<input name="domain" placeholder="yourbusiness.com" required></label>${['rankings','demand'].includes(kind)?'<label class="field">Search keyword<input name="keyword" placeholder="emergency plumber austin" maxlength="200" required></label>':''}<div class="grid2"><label class="field">Provider location code<input name="locationCode" type="number" min="1" value="2840" required><div class="hint">2840 = United States. Use a DataForSEO-supported city code for local research.</div></label><label class="field">Language<select name="language"><option value="en">English</option><option value="es">Spanish</option><option value="de">German</option><option value="fr">French</option></select></label></div>${kind==='rankings'?'<label class="field">Device<select name="device"><option value="desktop">Desktop</option><option value="mobile">Mobile</option></select></label><label class="field">Competitor domains (up to 3)<input name="competitors" placeholder="competitor.com, another.com"></label>':''}<div class="row"><button class="btn primary" type="submit">${kind==='rankings'?'Check rankings':kind==='demand'?'Research demand':kind==='traffic'?'Get traffic estimates':'Inspect backlink summary'} ↗</button><a href="${href('integrations')}" class="text-link">Connections</a></div></form></section><section class="panel"><div class="eyebrow muted">RESEARCH RESULTS</div><div id="serp-result" style="margin-top:20px"><h3>Start with a question.</h3><p style="font-size:12px">Your completed research will appear here, with its provider and configuration. Results are not guarantees or live Google Analytics data.</p></div></section></div>`;}
async function jobs(){shell(header('Every step, in view.','Track provider actions and inspect what actually happened.')+loading(),'jobs');try{const {jobs}=await api('/api/jobs');shell(header('Every step, in view.','Provider outcomes are recorded here. Inspect unknown outcomes before retrying.')+`<section class="panel">${jobs.length?jobs.map(j=>`<article class="activity-item"><div class="row between"><strong>${esc(j.kind)}</strong><span class="badge ${j.status==='failed'||j.status==='unknown'?'warn':''}">${esc(j.status)}</span></div><small class="muted">${esc(new Date(j.created).toLocaleString())} · ${esc(j.id.slice(0,8))}</small><pre class="result">${esc(JSON.stringify(j.result,null,2))}</pre></article>`).join(''):'<div class="empty"><h2>Your next steps will show here.</h2><p>Repository pushes, hosting requests and research tasks create activity records.</p></div>'}</section>`,'jobs');}catch(e){notify(e.message);}}
async function refresh(){const results=await Promise.all([api('/api/sites'),api('/api/connections')]);sites=results[0].sites;connections=results[1].connections;const wanted=new URLSearchParams(location.search).get('site');site=sites.find(s=>s.id===(wanted||site?.id))||sites[0]||null;}
async function screen(){switch(route){case'app':overview();break;case'editor':await editor();break;case'wp':converter();break;case'serp':serp();break;case'publish':publish();break;case'integrations':integrations();break;case'domains':domains();break;case'jobs':await jobs();break;default:overview();}}
async function save(){captureEdit();site=await api('/api/sites/'+site.id,{method:'PUT',body:site.data});dirty=false;await refresh();const state=document.getElementById('save-state');if(state)state.textContent='All changes saved';notify('Revision saved. Your export now includes these changes.');}
async function importZip(file){if(!file)return;dialog(loading('Opening your website ZIP…'));try{const r=await api('/api/import',{method:'POST',body:await file.arrayBuffer()});if(r.needsMapping){modalContent.innerHTML=`<h2>Map your imported content.</h2><div class="alert">${esc(r.warning)}</div><form id="map-import"><label class="field">Business name<input name="business" required></label><label class="field">Service area<input name="city" required></label><p class="hint">${r.pages.length} HTML pages found. Review imported text in the editor before exporting.</p><button class="btn primary" type="submit">Import as editable draft</button></form>`;document.getElementById('map-import').addEventListener('submit',async e=>{e.preventDefault();const info=Object.fromEntries(new FormData(e.target));const pages=r.pages.map((p,i)=>{const doc=new DOMParser().parseFromString(p.html,'text/html');doc.querySelectorAll('script,style,noscript,iframe,template').forEach(el=>el.remove());const headings=[...doc.querySelectorAll('h1,h2,h3')].slice(0,20);const sections=headings.map(h=>{let body='',node=h.nextElementSibling;while(node&&!/^H[123]$/.test(node.tagName)){if(['P','UL','OL','DIV'].includes(node.tagName))body+=node.textContent+'\n';node=node.nextElementSibling;}return{heading:h.textContent.slice(0,200),body:body.trim().slice(0,4000),cta:''};});return{slug:i===0?'home':p.name.replace(/.*\//,'').replace(/\.html?$/i,''),title:doc.title||'Imported page '+(i+1),description:'',sections:sections.length?sections:[{heading:doc.title||'Imported content',body:doc.body.textContent.slice(0,4000),cta:''}]};});try{const result=await api('/api/sites',{method:'POST',body:{...info,pages}});modal.close();location.href=href('editor','?site='+result.id);}catch(e){notify(e.message);}});return;}modal.close();location.href=href('editor','?site='+r.id);}catch(e){modal.close();notify(e.message);}}
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id||form.id==='map-import')return;e.preventDefault();const submit=form.querySelector('[type=submit]');const original=submit?.textContent;if(submit){submit.disabled=true;submit.textContent='Working…';}const b=Object.fromEntries(new FormData(form));try{
if(form.id==='auth-form'){const r=await api('/api/auth/'+(form.dataset.register==='true'?'register':'login'),{method:'POST',body:b});session=r;location.href=route==='login'?href('app'):location.href;}
if(form.id==='create-site'){const r=await api('/api/sites',{method:'POST',body:b});modal.close();location.href=href('editor','?site='+r.id);}
if(form.id==='connection-form'){await api('/api/connections/'+form.dataset.provider,{method:'PUT',body:b});await refresh();modal.close();integrations();notify('Credentials saved. Use a provider action to verify them.');}
if(form.id==='publish-form'){if(['cloudflare','render'].includes(b.host)&&!b.source)throw Error('Choose a source provider before triggering a repository-linked build.');const el=document.getElementById('publish-result');el.innerHTML=loading('Sending your website…');const r=await api(`/api/sites/${b['publish-project']}/publish`,{method:'POST',body:{source:b.source,host:b.host,reviewed:b.reviewed==='on'}});el.innerHTML=`<span class="badge ${r.partial?'warn':''}">${r.partial?'Partially completed':'Provider request completed'}</span><pre class="result">${esc(JSON.stringify(r,null,2))}</pre><a class="text-link" href="${href('jobs')}">Inspect activity →</a>`;}
if(form.id==='domain-form'){const el=document.getElementById('domain-result');el.innerHTML=loading('Asking your registrar…');const r=await api('/api/domains/search',{method:'POST',body:b});el.innerHTML=`<pre class="result">${esc(JSON.stringify(r,null,2))}</pre>`;}
if(form.id==='serp-form'){const el=document.getElementById('serp-result');el.innerHTML=loading('Research in progress…');const endpoint=form.dataset.kind==='rankings'?'check':form.dataset.kind;const r=await api('/api/serp/'+endpoint,{method:'POST',body:b});el.innerHTML=r.targets?`<div class="eyebrow muted">Google organic · ${esc(b.device)} · ${esc(b.locationCode)}</div><div class="table-scroll"><table><thead><tr><th>Domain</th><th>Position</th></tr></thead><tbody>${r.targets.map(t=>`<tr><td>${esc(t.domain)}</td><td>${t.position??'Not found in top 100'}</td></tr>`).join('')}</tbody></table></div><p class="hint">${esc(r.observedAt)} · DataForSEO · Cost ${esc(r.cost??'not reported')}</p><details><summary>Inspect organic results</summary><pre class="result">${esc(JSON.stringify(r.items,null,2))}</pre></details>`:`<pre class="result">${esc(JSON.stringify(r,null,2))}</pre>`;}
}catch(error){if(form.id==='auth-form')document.getElementById('auth-error').textContent=error.message;else{notify(error.message);for(const id of ['publish-result','domain-result','serp-result']){const el=document.getElementById(id);if(el&&el.querySelector('.progress-bar'))el.innerHTML=`<p class="error">${esc(error.message)}</p>`;}}}finally{if(submit){submit.disabled=false;submit.textContent=original;}}});
document.addEventListener('click',async e=>{const close=e.target.closest('[data-close]');if(close){modal.close();return;}const el=e.target.closest('button');if(!el)return;try{
if(el.dataset.configure)configure(el.dataset.configure);
if(el.dataset.disconnect){if(!confirm('Remove this provider connection from Sitocal?'))return;await api('/api/connections/'+el.dataset.disconnect,{method:'DELETE'});await refresh();integrations();}
if(el.dataset.convert){const siteId=document.getElementById('convert-project').value;location.href=`/api/sites/${siteId}/convert?format=${el.dataset.convert}`;}
if(el.dataset.serptab){serpTab=el.dataset.serptab;serp();}
if(el.dataset.device){document.getElementById('frame-wrap').classList.toggle('mobile',el.dataset.device==='mobile');document.querySelectorAll('[data-device]').forEach(x=>x.classList.toggle('active',x===el));}
if(el.dataset.revision){site=await api('/api/sites/'+site.id+'/restore',{method:'POST',body:{revision:el.dataset.revision}});dirty=false;await refresh();modal.close();editor();notify('Revision restored and saved as a new version.');}
switch(el.dataset.action){case'new-site':newSite();break;case'signup':auth(true);break;case'signin':auth(false);break;case'logout':await api('/api/auth/logout',{method:'POST',body:{}});location.href=href('landing');break;case'apply-edit':captureEdit();refreshFrame();notify('Preview updated. Save a revision to keep these changes.');break;case'save-site':el.disabled=true;try{await save();}finally{el.disabled=false;}break;
case'add-section':captureEdit();site.data.pages[pageIndex].sections.push({heading:'A new section.',body:'Tell customers something useful about your business.',cta:''});activeSection=site.data.pages[pageIndex].sections.length-1;editor();break;
case'remove-section':if(site.data.pages[pageIndex].sections.length<2)throw Error('Keep at least one section.');captureEdit();site.data.pages[pageIndex].sections.splice(activeSection,1);activeSection=0;editor();break;
case'section-up':case'section-down':{captureEdit();const arr=site.data.pages[pageIndex].sections,next=activeSection+(el.dataset.action==='section-up'?-1:1);if(next>=0&&next<arr.length){[arr[next],arr[activeSection]]=[arr[activeSection],arr[next]];activeSection=next;editor();}break;}
case'revisions':{const r=await api('/api/sites/'+site.id+'/revisions');dialog(`<h2>Revision history</h2><p style="font-size:12px">Restoring creates another saved revision. Unsaved edits will be replaced.</p>${r.revisions.map(v=>`<div class="row between" style="padding:12px 0;border-bottom:1px solid var(--line)"><small>${esc(new Date(v.created).toLocaleString())}</small><button class="btn small" data-revision="${v.id}">Restore</button></div>`).join('')}`);break;}
case'google-connect':{const r=await api('/api/google/start',{method:'POST',body:{}});location.href=r.url;break;}
case'google-properties':{el.disabled=true;try{const r=await api('/api/google/properties');const properties=(r.ga4.accountSummaries||[]).flatMap(a=>a.propertySummaries||[]);document.getElementById('google-properties').innerHTML=`<div class="google-properties"><label class="field">Search Console property<select id="gsc-property">${(r.gsc.siteEntry||[]).map(p=>`<option>${esc(p.siteUrl)}</option>`).join('')}</select><button class="btn small" style="margin-top:10px" data-action="gsc-report">Load search report</button></label><label class="field">GA4 property<select id="ga-property">${properties.map(p=>`<option value="${esc(p.property)}">${esc(p.displayName)}</option>`).join('')}</select><button class="btn small" style="margin-top:10px" data-action="ga-report">Load traffic report</button></label></div>`;}finally{el.disabled=false;}break;}
case'gsc-report':case'ga-report':{const gsc=el.dataset.action==='gsc-report',property=document.getElementById(gsc?'gsc-property':'ga-property').value;if(!property)throw Error('No property available. Check account permissions.');el.disabled=true;try{document.getElementById('google-result').innerHTML=loading('Loading Google report…');const r=await api('/api/google/report',{method:'POST',body:{kind:gsc?'gsc':'ga4',property}});document.getElementById('google-result').innerHTML=`<pre class="result">${esc(JSON.stringify(r,null,2))}</pre>`;}finally{el.disabled=false;}break;}
}
}catch(error){notify(error.message);}});
document.addEventListener('input',e=>{if(e.target.id?.startsWith('edit-')){dirty=true;const state=document.getElementById('save-state');if(state)state.textContent='Unsaved changes';}});
document.addEventListener('change',e=>{if(e.target.matches('[data-import]')){importZip(e.target.files[0]);return;}if(e.target.id==='editor-project'){if(dirty&&!confirm('Discard unsaved changes and switch project?')){e.target.value=site.id;return;}site=sites.find(s=>s.id===e.target.value);pageIndex=activeSection=0;dirty=false;editor();}if(e.target.id==='editor-page'){captureEdit();pageIndex=Number(e.target.value);activeSection=0;editor();}if(e.target.id==='editor-section'){captureEdit();activeSection=Number(e.target.value);editor();}});
window.addEventListener('message',e=>{const frame=document.getElementById('site-frame');if(!frame||e.source!==frame.contentWindow||e.data?.type!=='rankleem-edit')return;const [index,key]=String(e.data.field).split(':');if(!['heading','body','cta'].includes(key)||!site.data.pages[pageIndex].sections[Number(index)])return;captureEdit();activeSection=Number(index);const s=site.data.pages[pageIndex].sections[activeSection];document.getElementById('editor-section').value=index;for(const name of ['heading','body','cta'])document.getElementById('edit-'+name).value=s[name];document.getElementById('edit-'+key).focus();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function init(){if(route==='landing'){landing();return;}try{session=await api('/api/session');if(!session.user){auth(new URLSearchParams(location.search).get('signup')==='1');return;}if(route==='login'){location.href=href('app');return;}await refresh();await screen();}catch(e){root.innerHTML=`<div class="auth panel"><h1>Let’s reconnect.</h1><p>${esc(e.message)}</p><button class="btn primary" id="reload">Try again</button></div>`;document.getElementById('reload').onclick=()=>location.reload();}}
init();

